        score += 50.0 + (next_item_size - post_residual) as f64;
    }

    // 2. Proximity to bin_capacity (New bin logic):
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless fitting_bins_count is very low (forced opening).
    if bin_residual == bin_capacity {
        score += 40.0 - (fitting_bins_count as f64 * 15.0);
    }

    // 3. Harmonic alignment: Favor residuals that are multiples of common item sizes
    // or leave space for high-probability items (modeled by mean_residual).
    let alignment = (post_residual as f64 % 20.0).abs();
    score += alignment * 0.5;

    // 4. Density preservation: Penalize opening new bins if the current average
    // filling efficiency is already low.
    if bin_residual == bin_capacity && mean_residual > 30.0 {
        score += 30.0;
    }

    // 5. Lookahead efficiency: If the next item fits perfectly in the new post_residual,
    // reward this bin choice strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let waste_after_next = (post_residual - next_item_size) as f64;
        // Reward small remainder after next item
        score -= (100.0 - waste_after_next) * 0.2;
    }

    // 6. Scale by progression: As the stream nears the end, prioritize tight packing
    // over maintaining future flexibility.
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + (progress * 0.2);

    score
