pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small for future items.
    // If post_residual is < 10, it is likely unusable as the minimum item size is 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Penalize opening a new bin if other options exist, 
    // but allow it if the current bin's post_residual is highly inefficient.
    if bin_residual == bin_capacity {
        // This is the cost to open a new bin.
        // It is high, but we reduce it if the mean residual is already high (bin fragmentation).
        score = 45.0 + (mean_residual * 0.5);
    } else {
        // If this bin is the last one that can fit the item, reward it to keep options open for later.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }

        // Penalize fragmentation: higher open_bins_count increases the cost of keeping bins open.
        score += (open_bins_count as f64) * 0.2;
    }

    // 4. Progress Scaling: As we approach the end of the stream, be more conservative with bin usage.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
