        // Only open a new bin if the average residual is already high, 
        // suggesting current bins are too fragmented to be useful.
        score = 40.0 + (mean_residual * 0.5);
    } else {
        // 4. Fitting Pressure: If this is the only bin that fits the item, prioritize it.
