pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: favor smaller post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin early in the stream
    if is_new_bin {
        score += (1.0 - progress) * 45.0;
    }

    // Lookahead logic: if next item is large, avoid creating small residuals now
    if next_item_size > 0 {
        let tightness = (post_residual as f64) - (next_item_size as f64);
        if tightness < 0.0 {
            // If current placement makes the next item impossible to fit in this bin,
            // penalize based on how much space is wasted.
            score += (post_residual as f64).powf(1.5) * 0.1;
        } else {
            // Reward placements that leave exactly enough space for the next item
            score -= (1.0 / (tightness + 1.0)) * 10.0;
        }
    }

    // Penalize fragmented bins: if we have many open bins, prioritize filling them
    // rather than spreading out (unless the fit is truly excellent)
    if !is_new_bin {
        score += (open_bins_count as f64) * 0.5;

        // Non-linear penalty for "dead space" that is likely too small for future items
        if post_residual < 15 {
            score += (15.0 - post_residual as f64).powi(2) * 0.2;
        }
    }

    // If this is the last chance to fit the item in an existing bin, reduce penalty
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" that cannot fit typical items.
    // Residuals < 10 are often problematic; residuals near 10-20 are "slivers".
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // 2. Harmonic Lookahead: If next_item_size is large, favor larger post_residual
    // to accommodate it, otherwise favor tight packing (Best Fit).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalty for stranding the next item
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward for keeping space for the next item
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // 3. New Bin Thresholding:
    // If this is an empty bin (bin_residual == bin_capacity), penalize it 
    // unless all other options are very poor (high post_residual).
    if bin_residual == bin_capacity {
        score += 35.0; 
        // If we are forced to open a new bin, do it only if fitting_bins_count is low
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 10.0;
        }
    }

    // 4. Global state awareness:
    // As the stream progresses, become more aggressive about packing tightly.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (mean_residual * 0.2);

    // 5. Harmonic Class Logic:
    // Favor residuals that are multiples of common item sizes (e.g., 20, 25)
    if post_residual % 20 == 0 {
        score -= 5.0;
    }

    score
}
